#ifndef STDLIB_LAPACK_BASE_DPSTF2_VALIDATION_H
#define STDLIB_LAPACK_BASE_DPSTF2_VALIDATION_H

#include "stdlib/lapack/base/shared.h"
#include "stdlib/lapack/base/xerbla.h"
#include <limits.h>
#include <math.h>
#include <stddef.h>
#include <stdint.h>

typedef char dpstf2_lapack_integer_check[ ( sizeof( LAPACK_INT ) <= sizeof( intmax_t ) && (LAPACK_INT)-1 < 0 ) ? 1 : -1 ];
typedef char dpstf2_blas_integer_check[ ( sizeof( CBLAS_INT ) <= sizeof( intmax_t ) && (CBLAS_INT)-1 < 0 ) ? 1 : -1 ];

typedef struct dpstf2_envelope {
	uintptr_t first;
	uintptr_t last;
} dpstf2_envelope;

/**
* Returns the largest configured LAPACK integer.
*/
static intmax_t dpstf2_lapack_max( void ) {
	return (intmax_t)( UINTMAX_MAX >> ( (sizeof( uintmax_t )-sizeof( LAPACK_INT ))*CHAR_BIT + 1 ) );
}

/**
* Returns the largest configured BLAS integer independently of LAPACK_INT.
*/
static uintmax_t dpstf2_blas_max( void ) {
	return UINTMAX_MAX >> ( (sizeof( uintmax_t )-sizeof( CBLAS_INT ))*CHAR_BIT + 1 );
}

/**
* Computes a magnitude without negating a minimum signed integer.
*/
static uintmax_t dpstf2_magnitude( const intmax_t value ) {
	return value < 0 ? (uintmax_t)( -(value+1) )+1 : (uintmax_t)value;
}

/**
* Computes an exact, checked configured LAPACK integer product.
*/
static int dpstf2_product( const uintmax_t count, const intmax_t stride, intmax_t *result ) {
	const intmax_t limit = dpstf2_lapack_max();
	uintmax_t magnitude;
	uintmax_t bound;

	if ( count == 0 || stride == 0 ) {
		*result = 0;
		return 1;
	}
	magnitude = dpstf2_magnitude( stride );
	bound = (uintmax_t)limit + ( stride < 0 ? 1 : 0 );
	if ( count > bound/magnitude ) {
		return 0;
	}
	magnitude *= count;
	if ( stride < 0 ) {
		*result = magnitude == (uintmax_t)limit+1 ? -limit-1 : -(intmax_t)magnitude;
	} else {
		*result = (intmax_t)magnitude;
	}
	return 1;
}

/**
* Computes an exact, checked configured LAPACK integer sum.
*/
static int dpstf2_sum( const intmax_t x, const intmax_t y, intmax_t *result ) {
	const intmax_t limit = dpstf2_lapack_max();
	const intmax_t minimum = -limit-1;

	if ( ( y > 0 && x > limit-y ) || ( y < 0 && x < minimum-y ) ) {
		return 0;
	}
	*result = x+y;
	return 1;
}

/**
* Returns the greatest common divisor of two nonzero magnitudes.
*/
static uintmax_t dpstf2_gcd( uintmax_t x, uintmax_t y ) {
	uintmax_t remainder;

	while ( y != 0 ) {
		remainder = x%y;
		x = y;
		y = remainder;
	}
	return x;
}

/**
* Checks an inclusive physical byte envelope without forming derived pointers.
*/
static int dpstf2_envelope_valid( const void *data, const intmax_t first, const intmax_t last, const size_t size, dpstf2_envelope *envelope ) {
	const uintptr_t address = (uintptr_t)data;
	uintmax_t last_byte;
	uintmax_t first_byte;

	if ( first < 0 || last < first || (uintmax_t)last > ( (uintmax_t)PTRDIFF_MAX-(size-1) )/size ) {
		return 0;
	}
	first_byte = (uintmax_t)first*size;
	last_byte = (uintmax_t)last*size+(size-1);
	if ( last_byte > UINTPTR_MAX || address > UINTPTR_MAX-(uintptr_t)last_byte ) {
		return 0;
	}
	envelope->first = address+(uintptr_t)first_byte;
	envelope->last = address+(uintptr_t)last_byte;
	return 1;
}

/**
* Checks conservative physical byte-envelope overlap.
*/
static int dpstf2_overlap( const dpstf2_envelope *x, const dpstf2_envelope *y ) {
	return x->first <= y->last && y->first <= x->last;
}

/**
* Validates matrix geometry and reports the offending component (1,2,3).
*/
static int dpstf2_matrix_valid( const void *data, const intmax_t rows, const intmax_t columns, const intmax_t stride1, const intmax_t stride2, const intmax_t offset, dpstf2_envelope *envelope ) {
	uintmax_t magnitude1;
	uintmax_t magnitude2;
	uintmax_t divisor;
	intmax_t delta1;
	intmax_t delta2;
	intmax_t corner1;
	intmax_t corner2;
	intmax_t corner3;
	intmax_t first;
	intmax_t last;

	if ( ( rows > 1 && stride1 == 0 ) || !dpstf2_product( (uintmax_t)(rows-1), stride1, &delta1 ) ) {
		return 1;
	}
	if ( ( columns > 1 && stride2 == 0 ) || !dpstf2_product( (uintmax_t)(columns-1), stride2, &delta2 ) ) {
		return 2;
	}
	if ( rows > 1 && columns > 1 ) {
		magnitude1 = dpstf2_magnitude( stride1 );
		magnitude2 = dpstf2_magnitude( stride2 );
		divisor = dpstf2_gcd( magnitude1, magnitude2 );
		if ( magnitude2/divisor < (uintmax_t)rows && magnitude1/divisor < (uintmax_t)columns ) {
			return 2;
		}
	}
	if ( !dpstf2_sum( offset, delta1, &corner1 ) || !dpstf2_sum( offset, delta2, &corner2 ) || !dpstf2_sum( corner1, delta2, &corner3 ) ) {
		return 3;
	}
	first = offset;
	last = offset;
	if ( corner1 < first ) first = corner1;
	if ( corner2 < first ) first = corner2;
	if ( corner3 < first ) first = corner3;
	if ( corner1 > last ) last = corner1;
	if ( corner2 > last ) last = corner2;
	if ( corner3 > last ) last = corner3;
	return dpstf2_envelope_valid( data, first, last, sizeof( double ), envelope ) ? 0 : 3;
}

/**
* Guards every potential DSCAL/DSWAP call before factorization writes.
*
* Calls rebase operands to offset zero. Singleton strides normalize to one.
* The conservative count*abs(stride)+abs(stride)+1 bound covers signed
* casts, negative-stride rebasing, Fortran one-based indices, DSCAL's endpoint,
* both helpers' poststeps, and compiler loop-trip arithmetic. The count+2
* bound covers the unit-stride unrolled loop terminal independently.
*/
static int dpstf2_blas_valid( const intmax_t count, const intmax_t stride ) {
	const uintmax_t limit = dpstf2_blas_max();
	const uintmax_t length = (uintmax_t)count;
	const uintmax_t magnitude = dpstf2_magnitude( stride );

	if ( count <= 1 ) return 1;
	if ( length > limit-2 || magnitude == 0 || magnitude > limit ) return 0;
	return length+1 <= (limit-1)/magnitude;
}

/**
* Validates all active views and potential helper arithmetic before writes.
*
* The main flag selects public main9 error positions. Scalar validation and
* the active RANK envelope precede the safe-empty return. A, PIV and WORK
* are then validated in order, with overlap attributed to the later view.
*/
static LAPACK_INT dpstf2_validate( const int main, const LAPACK_UPLO uplo, const LAPACK_INT N, const double *A, const LAPACK_INT strideA1, const LAPACK_INT strideA2, const LAPACK_INT offsetA, const LAPACK_INT *PIV, const LAPACK_INT stridePIV, const LAPACK_INT offsetPIV, const LAPACK_INT *RANK, const LAPACK_INT offsetRANK, const double TOL, const double *WORK, const LAPACK_INT strideWORK, const LAPACK_INT offsetWORK ) {
	dpstf2_envelope rank;
	dpstf2_envelope a;
	dpstf2_envelope p;
	dpstf2_envelope w;
	intmax_t delta;
	intmax_t endpoint;
	intmax_t first;
	intmax_t last;
	int error;

	if ( uplo != LAPACK_UPPER_TRIANGLE && uplo != LAPACK_LOWER_TRIANGLE ) return main ? -2 : -1;
	if ( N < 0 || (intmax_t)N > dpstf2_lapack_max()/2 ) return main ? -3 : -2;
	if ( !isfinite( TOL ) ) return main ? -8 : -12;
	if ( RANK == NULL ) return main ? -7 : -10;
	if ( !dpstf2_envelope_valid( RANK, offsetRANK, offsetRANK, sizeof( LAPACK_INT ), &rank ) ) return main ? -7 : -11;
	if ( N == 0 ) return 0;
	if ( A == NULL ) return main ? -4 : -3;
	error = dpstf2_matrix_valid( A, N, N, strideA1, strideA2, offsetA, &a );
	if ( error != 0 ) return main ? -4 : (LAPACK_INT)(-3-error);
	if ( dpstf2_overlap( &rank, &a ) ) return main ? -4 : -3;
	if ( PIV == NULL ) return main ? -6 : -7;
	if ( ( N > 1 && stridePIV == 0 ) || !dpstf2_product( (uintmax_t)(N-1), stridePIV, &delta ) ) return main ? -6 : -8;
	if ( !dpstf2_sum( offsetPIV, delta, &endpoint ) ) return main ? -6 : -9;
	first = offsetPIV < endpoint ? offsetPIV : endpoint;
	last = offsetPIV > endpoint ? offsetPIV : endpoint;
	if ( !dpstf2_envelope_valid( PIV, first, last, sizeof( LAPACK_INT ), &p ) ) return main ? -6 : -9;
	if ( dpstf2_overlap( &rank, &p ) || dpstf2_overlap( &a, &p ) ) return main ? -6 : -7;
	if ( WORK == NULL ) return main ? -9 : -13;
	if ( strideWORK == 0 || !dpstf2_product( (uintmax_t)N*2-1, strideWORK, &delta ) ) return main ? -9 : -14;
	if ( !dpstf2_sum( offsetWORK, delta, &endpoint ) ) return main ? -9 : -15;
	first = offsetWORK < endpoint ? offsetWORK : endpoint;
	last = offsetWORK > endpoint ? offsetWORK : endpoint;
	if ( !dpstf2_envelope_valid( WORK, first, last, sizeof( double ), &w ) ) return main ? -9 : -15;
	if ( dpstf2_overlap( &rank, &w ) || dpstf2_overlap( &a, &w ) || dpstf2_overlap( &p, &w ) ) return main ? -9 : -13;
	if ( !dpstf2_blas_valid( N-1, strideA1 ) ) return main ? -5 : -4;
	if ( !dpstf2_blas_valid( N-1, strideA2 ) ) return -5;
	return 0;
}

/**
* Prints an adopted LAPACK diagnostic and returns this routine's status.
*/
static LAPACK_INT dpstf2_error( const char *name, const LAPACK_INT info ) {
	API_SUFFIX(lapack_xerbla)( name, info );
	return info;
}

#endif // !STDLIB_LAPACK_BASE_DPSTF2_VALIDATION_H
